def mark_old_rooms_started(apps, schema_editor):
    """加「房主按開始」之前的真人對戰：座位都坐滿的當成已經開始（原本最後一位加入就開始了），
    否則進行到一半的對局會卡住、誰都不能下。還有空位的照新規則，坐滿後由房主按開始。"""
    db = schema_editor.connection.alias
    Game = apps.get_model("arena", "Game")
    for game in Game.objects.using(db).filter(mode="pvp", started_at__isnull=True):
        if not game.players.filter(user__isnull=True).exists():
            game.started_at = game.created_at
            game.save(update_fields=["started_at"])


